use std::collections::BTreeSet;impl Solution{pub fn max_sum_submatrix(a:Vec<Vec<i32>>,k:i32)->i32{let(m,n)=(a.len(),a[0].len());let mut best=i32::MIN;for top in 0..m{let mut s=vec![0;n];for bot in top..m{for c in 0..n{s[c]+=a[bot][c]}let mut p=BTreeSet::new();p.insert(0);let mut cur=0;for &x in &s{cur+=x;if let Some(&v)=p.range(cur-k..).next(){best=best.max(cur-v)}p.insert(cur);}}}best}}
